<template><AppShell :title="pageTitle"><template #default="{ can, setError }"><v-tabs v-model="tab" grow density="compact"><v-tab value="settings">설정</v-tab><v-tab value="roles">역할·권한</v-tab><v-tab value="positions">직급</v-tab></v-tabs><v-window v-model="tab" class="mt-4"><v-window-item value="settings"><v-list><v-list-item v-for="s in data.settings" :key="s.id" :title="s.key" :subtitle="`${s.value} · ${s.description??''}`"/></v-list><v-form v-if="can('system.manage')" class="mt-3" @submit.prevent="saveSetting(setError)"><v-text-field v-model="setting.key" label="설정 키" variant="outlined"/><v-text-field v-model="setting.value" label="값" variant="outlined"/><v-select v-model="setting.type" :items="['string','integer','boolean','json']" label="타입" variant="outlined"/><v-text-field v-model="setting.description" label="설명" variant="outlined"/><v-btn type="submit" block>설정 저장</v-btn></v-form></v-window-item><v-window-item value="roles"><v-expansion-panels><v-expansion-panel v-for="r in data.roles" :key="r.id"><v-expansion-panel-title>{{ r.name }} ({{ r.code }})</v-expansion-panel-title><v-expansion-panel-text><v-chip v-for="p in r.permissions" :key="p.id" size="small" class="ma-1">{{ p.code }}</v-chip></v-expansion-panel-text></v-expansion-panel></v-expansion-panels></v-window-item><v-window-item value="positions"><v-list><v-list-item v-for="p in data.positions" :key="p.id" :title="p.name" :subtitle="`${p.code} · 순서 ${p.sort_order}`"/></v-list></v-window-item></v-window></template></AppShell></template>
<script setup>
import{onMounted,ref}from'vue';import AppShell from'../../components/layout/AppShell.vue';const pageTitle='시스템';const tab=ref('settings'),data=ref({settings:[],roles:[],permissions:[],positions:[]}),setting=ref({key:'',value:'',type:'string',description:''});async function load(){data.value=(await window.axios.get('/tillwhite/api/system')).data;}async function saveSetting(err){try{await window.axios.post('/tillwhite/api/system/settings',setting.value);await load();}catch(e){err(e.response?.data?.message??'설정 저장 실패');}}onMounted(load);
</script>
